def is_Sum_Of_Powers_Of_Two(n):
    # If n is 0, it cannot be represented as a sum of powers of 2
    if n == 0:
        return False

    # If n is odd, it cannot be represented as a sum of powers of 2
    if n % 2 != 0:
        return False

    # If n is even, check if it is a power of 2
    while n > 0:
        if n == 1:
            return True
        n = n >> 1  # Equivalent to n = n // 2
    return False
```

