def pancake_sort(arr):
    def flip(arr, n):
        """Flip the first n elements of the array."""
        for i in range(n // 2):
            arr[i], arr[n - i - 1] = arr[n - i - 1], arr[i]
        return arr

    n = len(arr)
    while n > 1:
        # Find the maximum element in the unsorted portion
        max_idx = n - 1
        for i in range(n - 1, 0, -1):
            if arr[i] > arr[max_idx]:
                max_idx = i
        # Flip the maximum element to its correct position
        flip(arr, max_idx)
        # If the maximum element is at the end, reduce the search space
        if max_idx != n - 1:
            n = max_idx
        else:
            n -= 1
    return arr
```

