def find_kth(arr1, arr2, k):
    # Find the maximum index of the smaller array
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)

    # If k is within the bounds of the smaller array
    if k <= len(arr1):
        return arr1[k-1]

    # If k is within the bounds of the larger array
    if k > len(arr1) + len(arr2) - 1:
        return arr2[k - len(arr1) - 1]

    # If k is within the bounds of the intersection
    i = len(arr1) - 1
    j = len(arr2) - 1
    while i >= 0 and j >= 0:
        if arr1[i] > arr2[j]:
            k -= 1
            j -= 1
        elif arr1[i] < arr2[j]:
            k -= 1
            i -= 1
        else:
            return arr1[i]
        i -= 1
        j -= 1
```

