def find_first_occurrence(arr, x):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                return mid
            else:
                right = mid - 1
        elif arr[mid] > x:
            right = mid - 1
        else:
            left = mid + 1
```

