def eulerian_num(n, m):
    # Base case: if m is 1, the only way to form a sequence of length n is to choose one element from m
    if m == 1:
        return 1
    else:
        # For other cases, use the formula for Eulerian numbers
        return (n - 1) * eulerian_num(n - 1, m - 1) + (n - m) * eulerian_num(n - 1, m)
