def get_total_number_of_sequences(m, n):
    # Base case: If n is 1, there is only one possible sequence
    if n == 1:
        return 1

    # If m is less than or equal to n, there are no valid sequences
    if m <= n:
        return 0

    # If n is less than m, there are m^(n-1) possible sequences
    if n < m:
        return m ** (n - 1)

    # If n is equal to m, there is only one possible sequence
    if n == m:
        return 1

    # If n is greater than m, there are m^(n-m) possible sequences
    if n > m:
        return m ** (n - m)
```

