def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for gap in range(n):
        for i in range(n - gap):
            j = i + gap
            if gap == 0:
                dp[i][j] = 1
            elif gap == 1:
                dp[i][j] = 2 if s[i] == s[j] else 1
            else:
                dp[i][j] = dp[i+1][j-1] + 1 if s[i] == s[j] else max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]
```

