def even_binomial_Coeff_Sum(n):
    sum_even = 0
    for i in range(n):
        if i % 2 == 0:
            sum_even += binomial_coeff(n, i)
    return sum_even

def binomial_coeff(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)  # Take advantage of symmetry
    result = 1
    for i in range(1, k + 1):
        result *= n - i + 1
        result /= i
    return int(result)
```

