def find_Rotations(s):
    def helper(s):
        if len(s) == 1: 
            return 0
        if len(s) == 2:
            return 0 if s[0] == s[1] else 1

        # Initial guess for the rotation
        i = int(len(s) / 2)
        temp = s[i:]
        temp = temp[::-1]

        if temp == s[:len(s) - i]:
            return 1 + helper(s[:i])
        else:
            return 1 + helper(s[:i+1])

    # Find the minimum rotations needed
    min_rotations = float('inf')
    for i in range(1, len(s) + 1):
        min_rotations = min(min_rotations, helper(s[:i]) if len(s) % i else helper(s[:i+1]))

    return min_rotations
```

