def remove_Occ(s, c):
    # Remove the last occurrence
    i = 0
    while i < len(s):
        if s[i] == c:
            s = s[:i] + s[i+1:]
            i = 0
        else:
            i += 1

    # Remove the first occurrence
    i = len(s) - 1
    while i > 0:
        if s[i] == c:
            s = s[:i] + s[i+1:]
            i = len(s) - 1
        else:
            i -= 1

    return s
