def next_smallest_palindrome(n):
    """ Finds the next smallest palindrome that is smaller than n. """
    reversed = int(str(n)[::-1])
    diff = reversed - n
    for step in range(1, abs(diff)):
        smaller_palin = str(n - step)
        if smaller_palin[::-1] == smaller_palin:
            return n - step
