def pancake_sort(lst):
    def flip(arr, index):
        # Flip the list from the start to the index (inclusive)
        arr[:index+1] = arr[index+1::-1]
        # Flip the list from the start to the index
        arr[:index+1] = arr[index+1::-1]

    n = len(lst)
    for i in range(n):
        # If the sublist is already sorted, stop
        if lst == sorted(lst):
            break
        # Find the maximum element and the index to flip
        max_i, max_value = None, None
        for j in range(n - 1, -1, -1):
            if lst[j] > max_value:
                max_i = j
                max_value = lst[j]
            elif max_value is not None:
                break
        # Flip the sublist starting from the current index
        if max_i is not None:
            flip(lst, max_i)
    return lst
