            position = lst.index(min(lst[:len(lst)-1], default=lst[0]))

        # If you have moved the minimum value to the rightmost position
        if position == len(lst) - 1:
            return lst, position

        if position != len(lst) - 1:
            # Perform the flip
            lst = lst[:position+1] + lst[position+1:len(lst)-1] + [lst[position+1]]
        else:
            lst = lst[:position] + [lst[position+1]]

        return pancake_sort_helper(lst, k=k+1)

    result = pancake_sort_helper(lst)
    return result[0]

# Test
assert pancake_sort([15, 79, 25, 38, 69]) == [15, 25, 38, 69, 79]
