def max_sub_array_sum_repeated(arr, k, n):
    # Apply Kadane's algorithm to find the maximum sum of subarray
    max_sum = max_sum_1 = max_sum_2 = sum_1 = sum_2 = 0

    # Iterate over k times
    for _ in range(k): 
        sum_1 += arr[n] 
        sum_2 += arr[n] 
        if sum_1 == sum_2: 
            sum_1 = sum_2 = 0 
        if sum_1 > max_sum_1: 
            max_sum_1 = sum_1 
        if sum_2 > max_sum_2: 
            max_sum_2 = sum_2 
        if sum_1 + sum_2 > max_sum: 
            max_sum = sum_1 + sum_2

    return max(max_sum_1, max_sum_2) // n
```

