def max_sum_increasing_subseq(array, i, k):
    # Get the sum of subsequence from prefix
    def sum_subseq_from_prefix(start, end):
        sum = 0
        for x in range(start, end):
            sum += array[x]
        return sum

    # Return the maximum sum of increasing subsequence from prefix to ith index + kth element
    def max_sum(end):
        if end < 0:
            return 0
        max_sum = float('-inf')
        for i in range(i+1, max(end-k, 0)+1):
            current_sum = sum_subseq_from_prefix(i, end)
            current_sum += max_sum(end - i)
            max_sum = max(max_sum, current_sum)
        return current_sum

    return max_sum(i+1)

