def max_sum_increasing_subseq(nums, m, n, k):
    dp = [nums[0], max(nums[0], nums[1])]
    store = {nums[0]: dp[0], nums[1]: dp[1]}

    for i in range(2, m):
        for j in range(i):
            if nums[i] > dp[j]:
                if nums[i] > store.get(dp[j], 0):
                    store[dp[j]] = dp[j]
                    dp[j] = nums[i]
            else:
                store[dp[j]] = dp[j]
                dp[j] = nums[i]
            if j + 1 > n:
                break
        if k == i:
            return sum(dp)
        else:
            store[nums[i]] = nums[i]
            dp.append(nums[i])

    return sum(dp)
