```python
def get_max_sum(n):
    if n == 1:
        return 0
    elif n == 2 or n == 3:
        return 1

    # Initialize the memoization table with base cases
    memo = {1: 0, 2: 1, 3: 1}

    # Recursive function to calculate the maximum sum
    def helper(n):
        # Base case
        if n in memo:
            return memo[n]

        # Handling division by zero
        if n % 2 or n % 3 or n % 4 or n % 5:
            return float('inf')

        # Finding the maximum sum
        memo[n] = helper(n / 2) + helper(n / 3) + helper(n / 4) + helper(n / 5) + n
        memo[n] = max(memo[n], helper(n // 2) + helper(n // 3) + helper(n // 4) + helper(n // 5) + n)
        return memo[n]

    result = helper(n)
    return result if result != float('inf') else -1
```

