def remove_consecutive_duplicates(lst: List[int]) -> List[int]:
    # Use a deque to keep track of the list without duplicates
    stack = collections.deque()
    for item in lst:
        if stack and stack[-1] == item:
            stack.pop()
        else:
            stack.append(item)
    return list(stack)
```

