def replace_specialchar(text):
    # Define the replacement dictionary
    replacements = {' ': '::', ',': '::', '.': '::'}

    # Use list comprehension to replace each character
    result = [replacements[char] if char in replacements else char for char in text]

    # Join the list into a string
    return ''.join(result)
