def left_insertion(lst, val):
    low = 0
    high = len(lst) - 1

    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == val:
            if mid-1 >= low and lst[mid-1] == val:
                return mid - 1
            else:
                return mid
        elif lst[mid] > val:
            high = mid - 1
        else:
            low = mid + 1

    return mid

