def tuple_to_dict(x):
    # If x is a tuple of tuples, convert it to a dictionary
    if isinstance(x, tuple) and len(x) > 0 and isinstance(x[0], tuple):
        # Initialize an empty dictionary to store key-value pairs
        dict_out = {}
        # Iterate through the tuple of tuples
        for k, v in x:
            # Append the pair as a key-value pair to the dictionary
            dict_out[k] = v
        return dict_out
    else:
        # If x is a simple tuple, convert it to a dictionary
        dict_out = {}
        for k, v in zip([x], [x]):
            dict_out[k] = v
        return dict_out

