def check_min_heap(arr):
    # Check if the binary tree is a min heap by ensuring that the parent node is smaller than its children
    def is_min_heap(node, idx):
        if node < arr[idx * 2 + 1] and node < arr[idx * 2 + 2]:
            # Recursively check left and right children
            if idx * 2 + 1 < len(arr):
                return is_min_heap(node, idx * 2 + 1)
            if idx * 2 + 2 < len(arr):
                return is_min_heap(node, idx * 2 + 2)
            return True
        return False

    # Start from the root and work down to the leaves
    if is_min_heap(arr[0], 0):
        return True
    return False
```

