def check_min_heap(arr):
    n = len(arr)
    for i in range(n // 2 - 1, -1, -1):
        max_child_index = largest_child_index(arr, i)
        if i != max_child_index:
            if arr[i] > arr[max_child_index]:
                return False
    return True

def largest_child_index(arr, root):
    left = 2 * root + 1
    right = 2 * root + 2
    if left < len(arr) and right < len(arr):
        if arr[left] > arr[left+1]:
            if arr[root] < arr[left]:
                return left
        else:
            if arr[root] < arr[left+1]:
                return left + 1
        elif arr[left] > arr[right]:
            if arr[root] < arr[right]:
                return left
        else:
            if arr[root] < arr[right]:
                return right
    elif right < len(arr):
        if arr[root] > arr[right]:
            return right
    else:
        return root

