def min_k(lst, k):
    lst.sort(key=lambda x: x[1])
    if len(lst) > k:
        return lst[:k]
    else:
        while len(lst) > k and lst[-1][0] <= lst[k-1][0]:
            lst.pop()
        return lst[:k]

