from collections import defaultdict

def unique_sublists(lst):
    # Using defaultdict to count occurrences of tuples
    unique_dict = defaultdict(int)
    for sublist in lst:
        for item in sublist:
            unique_dict[tuple(sorted([item]))] += 1

    # Converting tuples to dictionaries to return in a dictionary format
    result = {}
    for item, count in unique_dict.items():
        result[item] = count

    return result
