def check_expression(expr):
    def is_curly_square_open(char):
        return char in "([{"

    def is_curly_square_closed(char):
        return char in ")]}"

    def is_double_open(char1, char2):
        return char1 in "{[(" and char2 in "}{])}"

    def is_double_closed(char1, char2):
        return char1 in "{}[]" and char2 in "}{])"

    stack = []
    for char in expr:
        if is_curly_square_open(char):
            stack.append(char)
        elif is_curly_square_closed(char):
            if len(stack) == 0 or not is_double_closed(stack.pop(), char):
                return False
    return len(stack) == 0
