def find_sum(lst):
    # Initialize sum to 0
    sum = 0
    # Use a dictionary to count occurrences of elements
    counts = {}
    for item in lst:
        # If item is not in counts, add it
        if item not in counts:
            counts[item] = 1
        # If item is already in counts, subtract its count
        elif item in counts:
            counts[item] += 1
        sum += item

    # Sum up the elements that are not repeated
    for item in lst:
        # If item is not in counts, subtract its count
        if counts[item] == 0:
            sum -= item

    return sum
```

