from typing import Tuple, Iterable, Union

def remove_nested(t: Tuple[Union[int, Iterable], ...]) -> Tuple[Union[int, Iterable], ...]:
    """Remove nested tuples from the given tuple."""
    new_t = ()
    for item in t:
        if isinstance(item, tuple):
            new_t += (item,)
        else:
            new_t += (item,)
    return new_t
```

