def last(arr, x):
    # Check if the last element in the array is x
    if len(arr) > 0 and arr[-1] == x:
        # If so, return its index starting from the end of the array
        return len(arr) - 1
    else:
        # Otherwise, iterate backwards to find the last index of x
        for i in range(len(arr)-1, -1, -1):
            if arr[i] == x:
                return i
