def last(lst, x):
    left, right = 0, len(lst) - 1
    while left < right:
        mid = left + (right - left) // 2
        if lst[mid] == x:
            right = mid
        elif lst[mid] > x:
            right = mid - 1
        else:
            left = mid + 1
    return left
